/**
 * Miniaturas del catálogo de bloques: dibujos simples (SVG) de cómo se ve cada bloque en la web.
 * Devuelve tipo => SVG. Al sumar un tipo de bloque, agregá acá su dibujo.
 */

$g = '#bd944f'; // dorado
$n = '#111';    // negro
$l = '#d9d3c5'; // líneas
$f = '#efe9dc'; // fondo foto
$lineas = static fn(int $x, int $y, array $anchos, string $c = '#d9d3c5', int $alto = 4) => implode('', array_map(
    fn($w, $i) => "<rect x='$x' y='" . ($y + $i * 9) . "' width='$w' height='$alto' rx='2' fill='$c'/>", $anchos, array_keys($anchos)));
$svg = static fn(string $c) => "<svg viewBox='0 0 120 72' xmlns='http://www.w3.org/2000/svg' aria-hidden='true'>$c</svg>";
$foto = static fn(int $x, int $y, int $w, int $h) => "<rect x='$x' y='$y' width='$w' height='$h' fill='$f'/><path d='M" . ($x + 4) . ' ' . ($y + $h - 4) . ' l' . (int) ($w * .3) . ' -' . (int) ($h * .45) . ' l' . (int) ($w * .2) . ' ' . (int) ($h * .25) . ' l' . (int) ($w * .15) . ' -' . (int) ($h * .15) . ' l' . (int) ($w * .25) . " " . (int) ($h * .35) . "z' fill='$l'/>";

return [
    'texto' => $svg($lineas(10, 12, [100, 92, 100, 70]) . "<rect x='10' y='52' width='6' height='6' fill='$g'/>" . $lineas(22, 53, [70])),
    'introduccion' => $svg($lineas(10, 18, [100, 100, 76], '#b5ae9f', 6)),
