    'documentos' => $svg("<rect x='8' y='14' width='50' height='44' fill='none' stroke='$l' stroke-width='2'/><rect x='62' y='14' width='50' height='44' fill='none' stroke='$l' stroke-width='2'/><rect x='14' y='22' width='12' height='16' fill='$g'/><rect x='68' y='22' width='12' height='16' fill='$g'/>" . $lineas(14, 44, [36]) . $lineas(68, 44, [36])),
